local function newObject(o, class)
    class.__index = class
    return setmetatable(o, class)
end

local s_vsh = [[
attribute vec2 vPosition;
varying vec2 vUV0;

uniform float angle;
uniform int dir;
uniform mat4 spriteModelViewProjection;
uniform vec2 canvasSize;

void main()
{
    vUV0 = (vPosition.xy + 1.0) / 2.0;
    vec2 texSize = canvasSize / 2.0;
    vec3 pos = vec3(vPosition * texSize, 0.0);

    vec3 result = pos;

    float k = vUV0.x;
    float r = angle;
    if (dir == 0)
    {
        if (r < 180.0)
        {
            result.y = pos.y * cos(k * r * 3.14 / 180.0);
            result.z = pos.y * sin(k * r * 3.14 / 180.0);
        }
        else
        {
            k = 1.0 - vUV0.x;
            r = 360.0 - r;
            result.y = -pos.y * cos(k * r * 3.14 / 180.0);
            result.z = pos.y * sin(k * r * 3.14 / 180.0);
        }
    }
    else
    {
        if (r < 180.0)
        {
            result.y = pos.y * cos(k * r * 3.14 / 180.0);
            result.z = -pos.y * sin(k * r * 3.14 / 180.0);
        }
        else
        {
            k = 1.0 - vUV0.x;
            r = 360.0 - r;
            result.y = -pos.y * cos(k * r * 3.14 / 180.0);
            result.z = -pos.y * sin(k * r * 3.14 / 180.0);
        }
    }
    gl_Position = spriteModelViewProjection * vec4(result, 1.0);
}
]]

